def simulate(rounds, h_max):
    heights = [0] * 9
    for r in range(rounds):
        # Gardener adds 1 to all
        for i in range(9):
            heights[i] += 1
        # Lumberjack removes 1 from 4 tallest
        # Sort heights in descending order to find the tallest
        sorted_indices = sorted(range(9), key=lambda i: heights[i], reverse=True)
        for i in range(4):
            idx = sorted_indices[i]
            if heights[idx] > 0:
                heights[idx] -= 1
    return heights

print(simulate(100, 10))
print(simulate(1000, 10))
